+        verifyShort();
+    }
+
+    @Test
+    @IR(counts = { IRNode.AARCH64_VNOT_AND, ">= 1" },
+        applyIfCPUFeature = { "asimd", "true" })
+    public static void testNotAndCommutativeInt() {
+        IntVector va = IntVector.fromArray(I_SPECIES, ia, 0);
