+        vb.and(va).lanewise(VectorOperators.XOR, vb).intoArray(ir, 0);
+        verifyInt();
+    }
+
+    @Test
+    @IR(counts = { IRNode.AARCH64_VNOT_AND, ">= 1" },
+        applyIfCPUFeature = { "asimd", "true" })
+    public static void testNotAndCommutativeLong() {
